from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(7))  # D0..D6
    units = list(range(5))  # U0..U4
    supplies = list(range(3))  # S0..S2
    days = list(range(4))  # Day0..Day3

    demands = [[[44.44, 28.84, 37.33, 31.99], [48.26, 13.97, 39.2, 14.72], [12.24, 21.75, 21.18, 37.06]], [[19.81, 14.56, 39.02, 47.94], [22.55, 40.87, 43.57, 30.68], [40.11, 26.48, 21.86, 46.59]], [[31.25, 13.69, 30.71, 11.44], [42.55, 26.02, 10.86, 16.86], [38.35, 31.34, 41.83, 42.85]], [[15.36, 38.74, 37.12, 26.3], [35.24, 12.82, 21.29, 29.65], [39.8, 49.76, 16.96, 29.32]], [[16.61, 43.46, 39.65, 28.51], [26.14, 30.35, 39.05, 33.94], [28.12, 31.2, 36.25, 16.54]]]
    depot_supplies = [[[19.81, 23.69, 32.32, 20.48], [22.5, 20.09, 28.49, 26.65], [19.81, 34.35, 27.36, 36.39]], [[18.86, 28.54, 38.36, 23.95], [37.15, 14.48, 17.64, 26.5], [28.88, 24.55, 28.38, 21.23]], [[27.12, 18.41, 37.83, 23.49], [23.9, 20.56, 18.78, 17.95], [18.68, 27.41, 24.11, 32.66]], [[26.47, 19.91, 23.59, 28.79], [22.54, 25.81, 26.5, 16.13], [28.58, 27.28, 16.47, 32.68]], [[24.3, 18.2, 25.99, 27.49], [35.84, 24.73, 25.44, 17.4], [21.84, 31.55, 24.97, 30.96]], [[27.02, 23.25, 33.93, 17.44], [28.53, 18.56, 31.98, 26.0], [32.18, 24.95, 25.59, 20.33]], [[15.94, 28.39, 22.56, 23.92], [35.09, 20.47, 23.38, 17.6], [24.55, 21.53, 27.28, 31.46]]]
    transport_costs = [[4.13, 3.44, 4.1, 2.75, 4.31], [2.41, 4.91, 3.21, 4.78, 3.65], [1.68, 3.51, 2.6, 4.87, 3.0], [3.17, 2.61, 4.05, 4.67, 3.06], [4.7, 4.49, 1.27, 1.04, 1.04], [1.47, 4.02, 3.51, 4.34, 2.69], [3.12, 2.1, 3.29, 1.59, 3.59]]
    risk_costs = [[186.65, 147.7, 109.74, 190.9, 150.57], [110.67, 159.32, 78.82, 118.21, 149.3], [136.58, 82.49, 127.98, 153.68, 188.31], [133.63, 114.92, 82.86, 128.56, 90.5], [63.85, 147.64, 109.42, 118.34, 150.88], [97.68, 104.6, 187.88, 153.66, 184.19], [131.3, 94.53, 186.77, 187.63, 83.83]]
    supply_volumes = [1.95, 1.02, 1.51]
    penalty_costs = [86.73, 52.89, 93.17]
    vehicle_cost = 10.0
    vehicle_capacity = 73.0
    total_vehicles = 27

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
